function compareClocks(a, b) {
  let aBig = false, bBig = false;
  for (const n of new Set([...Object.keys(a), ...Object.keys(b)])) {
    const x = a[n] ?? 0, y = b[n] ?? 0;
    if (x > y) aBig = true;
    if (y > x) bBig = true;
  }
  if (aBig && bBig) return "concurrent";
  if (aBig) return "a-after-b";
  if (bBig) return "b-after-a";
  return "equal";
}

function resolve(versions) {
  return versions.filter((v, i) =>
    !versions.some((w, j) => {
      const c = compareClocks(w.clock, v.clock);
      return c === "a-after-b" || (c === "equal" && j < i);
    })
  );
}

resolve([
  { value: "x", clock: { A: 1 } },
  { value: "y", clock: { A: 2 } },
  { value: "z", clock: { A: 1, B: 1 } },
]); // y and z (concurrent); x is dominated by both
